{
  "verdict": "request_changes",
  "summary": "candidate.py incorrectly updates the state when version equals the current state version, violating the strict greater-than requirement.",
  "findings": [
    {
      "finding_id": "equality_threshold_violation",
      "file": "candidate.py",
      "line_start": 2,
      "line_end": 2,
      "severity": "high",
      "description": "The condition `version >= state['version']` triggers on equality, but the contract requires updates only when version is strictly greater than state[version].",
      "evidence": "SPEC.md mandates: 'Apply the update only when version is strictly greater than state[version]... Equal or older versions return False and must leave the entire state unchanged.' candidate.py line 2 uses `>=`, causing state mutation and True return for equal versions, e.g., advance({'version': 2, 'value': 'a', 'writes': 0}, 2, 'b')."
    }
  ]
}
